#include <iostream>
#include <vector>
#include <string>
#include <map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string start;
    cin >> start;
    string end;
    cin >> end;
    long long k;
    cin >> k;
    vector<string> bank(k);
    for (int i = 0; i < k; i++) cin >> bank[i];

    auto oneApart = [](const string& a, const string& b) {
        int differences = 0;
        for (size_t i = 0; i < a.size(); i++) {
            if (a[i] != b[i]) differences++;
        }
        return differences == 1;
    };
    map<string, int> dist;
    dist[start] = 0;
    vector<string> queue = {start};
    for (size_t i = 0; i < queue.size(); i++) {
        string gene = queue[i];
        for (const string& other : bank) {
            if (!dist.count(other) && oneApart(gene, other)) {
                dist[other] = dist[gene] + 1;
                queue.push_back(other);
            }
        }
    }
    cout << (dist.count(end) ? dist[end] : -1) << "\n";

    return 0;
}

