import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String start = next();
        String end = next();
        long k = Long.parseLong(next());
        String[] bank = new String[(int) k];
        for (int i = 0; i < bank.length; i++) bank[i] = next();

        Map<String, Integer> dist = new HashMap<>();
        dist.put(start, 0);
        List<String> queue = new ArrayList<>();
        queue.add(start);
        for (int i = 0; i < queue.size(); i++) {
            String gene = queue.get(i);
            for (String other : bank) {
                if (dist.containsKey(other)) continue;
                int differences = 0;
                for (int p = 0; p < gene.length(); p++) {
                    if (gene.charAt(p) != other.charAt(p)) differences++;
                }
                if (differences == 1) {
                    dist.put(other, dist.get(gene) + 1);
                    queue.add(other);
                }
            }
        }
        System.out.println(dist.containsKey(end) ? dist.get(end) : -1);
    }
}
